import java.util.Set;

public class ColoredBadgeTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ColoredBadge red7 = new ColoredBadge(7, "red");
        ColoredBadge red7again = new ColoredBadge(7, "red");
        ColoredBadge blue7 = new ColoredBadge(7, "blue");
        Badge plain7 = new Badge(7);

        check("same id and color are equal", true, red7.equals(red7again));
        check("same id but a different color is not equal", false, red7.equals(blue7));
        check("a colored badge is not equal to a plain badge", false, red7.equals(plain7));
        check("and the comparison is symmetric", false, plain7.equals(red7));
        check("equals(null) is false", false, red7.equals(null));
        check("equal badges share a hashCode", true, red7.hashCode() == red7again.hashCode());
        check("toString", "ColoredBadge(7,red)", red7.toString());

        Set<Object> set = new HashSet<>();
        set.add(plain7);
        set.add(red7);
        set.add(red7again);
        set.add(blue7);
        check("a HashSet keeps three distinct badges", 3, set.size());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

