import java.util.Objects;

/**
 * TASK: Complete equals, hashCode and toString on ColoredBadge so the
 * equals contract still holds ACROSS the hierarchy. The Badge class above
 * it is provided and already works -- do not change it.
 *
 * Badge compares with getClass(), so a plain Badge is never equal to a
 * ColoredBadge in either direction (that is symmetry). Your override must
 * keep that property and additionally compare the color.
 *
 * Rules:
 *   - two ColoredBadges are equal when they have the same id AND the same
 *     color (reuse super.equals for the id half)
 *   - equal objects must produce equal hashCodes -- Objects.hash of the
 *     inherited hash and the color works
 *   - toString returns "ColoredBadge(7,red)"
 *   - equals(null) and equals of an unrelated type are false
 *
 * Example: new ColoredBadge(7, "red").equals(new Badge(7)) is false, and so
 *   is new Badge(7).equals(new ColoredBadge(7, "red")).
 */
class Badge {

    private final int id;

    Badge(int id) {
        this.id = id;
    }

    public int getId() {
        return id;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }
        return id == ((Badge) other).id;
    }

    @Override
    public int hashCode() {
        return Integer.hashCode(id);
    }

    @Override
    public String toString() {
        return "Badge(" + id + ")";
    }
}

public class ColoredBadge extends Badge {

    private final String color;

    public ColoredBadge(int id, String color) {
        super(id);
        this.color = color;
    }

    public String getColor() {
        return color;
    }

    @Override
    public boolean equals(Object other) {
        if (!super.equals(other)) {
            return false;
        }
        ColoredBadge that = (ColoredBadge) other;
        return Objects.equals(color, that.color);
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), color);
    }

    @Override
    public String toString() {
        return "ColoredBadge(" + getId() + "," + color + ")";
    }
}
